import xml.etree.ElementTree as ET
tree = ET.parse('/work/output/artifacts/skill-bpmn-script-jint-lifecycle/ScriptNormalizer/ScriptNormalizer/ScriptNormalizer.bpmn')
root = tree.getroot()
print('Parsed OK, root tag:', root.tag)

BPMN = 'http://www.omg.org/spec/BPMN/20100524/MODEL'
UIPATH = 'http://uipath.org/schema/bpmn'

process = root.find(f'{{{BPMN}}}process')
print('Process id:', process.get('id'))

# Collect all ids
ids = set()
def collect_ids(elem):
    if elem.get('id'): ids.add(elem.get('id'))
    for c in elem: collect_ids(c)
collect_ids(root)

# Check all refs
errors = []
for elem in root.iter():
    for attr in ('sourceRef','targetRef','attachedToRef','bpmnElement','default'):
        val = elem.get(attr)
        if val and val not in ids:
            errors.append(f'{attr}={val} not found (on {elem.tag})')

# Check BPMNDiagram present
diag = root.find('.//{http://www.omg.org/spec/BPMN/20100524/DI}BPMNDiagram')
if diag is None:
    errors.append('Missing BPMNDiagram')

# Count shapes and flows
shapes = list(root.iter('{http://www.omg.org/spec/BPMN/20100524/DI}BPMNShape'))
edges = list(root.iter('{http://www.omg.org/spec/BPMN/20100524/DI}BPMNEdge'))
print(f'BPMNShapes: {len(shapes)}, BPMNEdges: {len(edges)}')

# Check variables referenced in script mapping
import re
for elem in root.iter('{http://uipath.org/schema/bpmn}input'):
    content = elem.text or ''
    refs = re.findall(r'=vars\.(\w+)', content)
    for r in refs:
        if r not in ids:
            errors.append(f'vars.{r} not declared')
for elem in root.iter('{http://uipath.org/schema/bpmn}output'):
    var_ref = elem.get('var','')
    if var_ref and var_ref not in ids:
        errors.append(f'output var={var_ref} not declared')

if errors:
    for e in errors: print('ERROR:', e)
else:
    print('VALID - no structural issues found')
"
